import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x_val = sc.nextLong();
        long y_val = sc.nextLong();
        long max_b = sc.nextLong();

        double min_diff = 1e15; // a large number to simulate INF_NUM
        long answer_b = 1;
        long answer_a = 0;

        for (long b = 1; b <= max_b; b++) {
            long a1 = (x_val * b) / y_val;
            long a2 = a1 + 1;

            checkAndSave(x_val, y_val, b, a1, min_diff, answer_b, answer_a);
            checkAndSave(x_val, y_val, b, a2, min_diff, answer_b, answer_a);
        }

        System.out.println(answer_a + "/" + answer_b);
    }

    private static void checkAndSave(long x_val, long y_val, long b, long a, double min_diff, long answer_b, long answer_a) {
        double diff = Math.abs((double)a / b - (double)x_val / y_val);
        if (diff + 1e-15 < min_diff) {
            min_diff = diff;
            answer_b = b;
            answer_a = a;
        }
    }
}

